<?php declare(strict_types=1); use Core\Http\Router; use Modules\Languages\Controllers\LanguageController; return function (Router $router): void { $router->get('/lang/{code}', [LanguageController::class, 'switchLocale']) ->middleware('web') ->where('code', '[a-zA-Z_-]{2,10}') ->name('lang.switch'); $router->group([ 'prefix' => 'admin/languages', 'middleware' => ['web', 'auth'], 'name' => 'admin.languages.', ], function (Router $router): void { $router->get('/', [LanguageController::class, 'index']) ->middleware('permission:languages.manage') ->name('index'); $router->post('/', [LanguageController::class, 'store']) ->middleware('permission:languages.manage') ->name('store'); $router->post('/{id}/toggle', [LanguageController::class, 'toggle']) ->middleware('permission:languages.manage') ->where('id', '\d+') ->name('toggle'); }); }; 